<template>
  <div class="planning-page">
    <canvas ref="bgCanvas" class="bg-canvas"></canvas>

    <div class="page-header">
      <div class="header-left">
        <button class="back-btn" @click="goBack">
          <svg viewBox="0 0 24 24" width="18" height="18">
            <path d="M15 18l-6-6 6-6" fill="none" stroke="currentColor" stroke-width="2"/>
          </svg>
          <span>返回</span>
        </button>
        <h1 class="page-title">学业-就业双向联动规划</h1>
        <span class="page-subtitle">基于学业数据与就业市场的智能联动规划系统</span>
      </div>
      <div class="header-nav">
        <span class="nav-item" :class="{ active: currentNav === 'skill-route' }" @click="handleNavClick('skill-route')">学习路线</span>
        <span class="nav-item" :class="{ active: currentNav === 'resource-lib' }" @click="handleNavClick('resource-lib')">资源推送</span>
        <span class="nav-item" :class="{ active: currentNav === 'ai-assistant' }" @click="handleNavClick('ai-assistant')">AI答疑</span>
        <span class="nav-item" :class="{ active: currentNav === 'dashboard' }" @click="handleNavClick('dashboard')">个人中心</span>
      </div>
    </div>

    <div class="main-layout" :class="{ 'ai-mode': currentNav === 'ai-assistant', 'no-ai-sidebar': currentNav !== 'ai-assistant' }">
      <aside class="sidebar">
        <div class="sidebar-section">
          <div class="section-label">功能导航</div>
          <div 
            v-for="item in navItems" 
            :key="item.key" 
            class="nav-item"
            :class="{ active: currentNav === item.key }"
            @click="handleNavClick(item.key)"
          >
            <span class="nav-icon" v-html="item.icon"></span>
            <span class="nav-text">{{ item.label }}</span>
          </div>
        </div>
      </aside>

      <main class="content-area">
        <!-- 个人学习数据分析视图 -->
        <div v-if="currentNav === 'dashboard'" class="view-section">
          <div class="content-header">
            <h2>个人学习数据分析</h2>
            <p class="content-desc">实时追踪你的学习进度和成果</p>
          </div>
          <div class="stats-grid">
            <div class="stat-card">
              <div class="stat-icon blue">📚</div>
              <div class="stat-content">
                <h3>已学资源</h3>
                <p class="stat-value">{{ learnedCount }}</p>
                <span class="stat-label">个学习资源</span>
              </div>
            </div>
            <div class="stat-card">
              <div class="stat-icon green">⏱</div>
              <div class="stat-content">
                <h3>学习时长</h3>
                <p class="stat-value">{{ totalHours }}</p>
                <span class="stat-label">小时累计</span>
              </div>
            </div>
            <div class="stat-card">
              <div class="stat-icon orange">🎯</div>
              <div class="stat-content">
                <h3>技能掌握</h3>
                <p class="stat-value">{{ masteryRate }}%</p>
                <span class="stat-label">平均掌握率</span>
              </div>
            </div>
            <div class="stat-card">
              <div class="stat-icon purple">📈</div>
              <div class="stat-content">
                <h3>连续学习</h3>
                <p class="stat-value">{{ streakDays }}</p>
                <span class="stat-label">天连续打卡</span>
              </div>
            </div>
          </div>
          <div class="chart-section">
            <h3 class="chart-title">📊 技能掌握进度</h3>
            <div class="progress-list">
              <div v-for="skill in topSkills" :key="skill.name" class="progress-item">
                <div class="progress-header">
                  <span class="progress-name">{{ skill.name }}</span>
                  <span class="progress-percent">{{ skill.progress }}%</span>
                </div>
                <div class="progress-bar">
                  <div class="progress-fill" :style="{ width: skill.progress + '%' }"></div>
                </div>
              </div>
            </div>
          </div>
        </div>

        <!-- 行业技能路线视图 -->
        <div v-else-if="currentNav === 'skill-route'" class="view-section">
          <div class="content-header">
            <h2>行业技能路线</h2>
            <p class="content-desc">{{ selectedPosition ? '当前岗位：' + selectedPositionLabel + ' · 系统生成的阶梯式学习路径' : '查看IT行业各岗位技能成长路径' }}</p>
          </div>

          <!-- 未选择岗位：显示引导 -->
          <div v-if="!selectedPosition" class="route-placeholder">
            <div class="placeholder-icon">🚀</div>
            <h3>技能路线规划</h3>
            <p>选择目标岗位后，系统将为你生成完整的技能成长路线图</p>
            <button class="action-btn primary" @click="currentNav = 'resource-lib'">前往选择岗位</button>
          </div>

          <!-- 已选择岗位：显示技能路线 -->
          <template v-else>
            <div class="route-header">
              <div class="route-title-area">
                <h2>🎓 {{ selectedPositionLabel }} · 学习路线图</h2>
                <p class="route-desc">基于岗位 JD 技能清单，系统自动生成五阶段阶梯式学习路径</p>
              </div>
              <div class="route-stats">
                <div class="stat-item">
                  <span class="stat-value">{{ routeStages.length }}</span>
                  <span class="stat-label">学习阶段</span>
                </div>
                <div class="stat-item">
                  <span class="stat-value">{{ totalRouteSkills }}</span>
                  <span class="stat-label">技能点</span>
                </div>
                <div class="stat-item">
                  <span class="stat-value">20</span>
                  <span class="stat-label">周计划</span>
                </div>
              </div>
            </div>

            <div class="timeline-container">
              <div v-for="(stage, idx) in routeStages" :key="stage.id || idx" class="stage-card">
                <div class="stage-header">
                  <div class="stage-icon" :style="{ background: stage.color + '20', borderColor: stage.color }">
                    <span>{{ stage.icon }}</span>
                  </div>
                  <div class="stage-meta">
                    <h3 class="stage-name">{{ stage.name }}</h3>
                    <p class="stage-desc">{{ stage.desc }}</p>
                  </div>
                  <div class="stage-badge" :style="{ background: stage.color + '20', color: stage.color }">
                    {{ stage.weeks }}
                  </div>
                </div>
                <div class="stage-body">
                  <div class="skills-list">
                    <div v-for="(skill, sIdx) in stage.skills" :key="sIdx" class="skill-block" :class="'level-' + skill.level">
                      <div class="skill-item">
                        <div class="skill-info">
                          <span class="skill-name">{{ skill.name }}</span>
                          <span v-if="skill.category" class="skill-category">{{ skill.category }}</span>
                        </div>
                        <span class="skill-level" :class="'level-' + skill.level">{{ levelLabelCN[skill.level] || skill.level }}</span>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </template>
        </div>

        <!-- 我的学习计划视图 -->
        <div v-else-if="currentNav === 'study-plan'" class="view-section">
          <div class="content-header">
            <h2>我的学习计划</h2>
            <p class="content-desc">管理你的学习任务和目标</p>
          </div>
          <div class="plan-list" v-if="studyPlans.length > 0">
            <div v-for="plan in studyPlans" :key="plan.id" class="plan-item">
              <div class="plan-header">
                <h4>{{ plan.title }}</h4>
                <span class="plan-status" :class="plan.status">{{ plan.statusText }}</span>
              </div>
              <p class="plan-desc">{{ plan.desc }}</p>
              <div class="plan-progress">
                <div class="progress-bar">
                  <div class="progress-fill" :style="{ width: plan.progress + '%' }"></div>
                </div>
                <span class="progress-text">{{ plan.progress }}%</span>
              </div>
              <div class="plan-meta">
                <span>📅 截止: {{ plan.deadline }}</span>
                <span>🎯 目标: {{ plan.goal }}</span>
              </div>
            </div>
          </div>
          <div v-else class="empty-state">
            <div class="empty-icon">📋</div>
            <h3>暂无学习计划</h3>
            <p>选择岗位并开始学习，系统将为你自动生成学习计划</p>
            <button class="action-btn primary" @click="currentNav = 'resource-lib'">前往选择岗位</button>
          </div>
        </div>

        <!-- 推荐资源库视图 -->
        <div v-else-if="currentNav === 'resource-lib'" class="view-section">
          <div class="content-header">
            <h2>为你推荐的学习资源</h2>
            <p class="content-desc">根据你的目标岗位、学习进度和薄弱技能，系统自动推送资源</p>
          </div>

          <div class="job-selector">
            <div class="selector-label">
              <span class="label-icon">🎯</span>
              <span>选择目标岗位</span>
            </div>
            <div class="selector-wrapper">
              <select v-model="selectedPosition" class="position-select" @change="onPositionChange">
                <option value="">-- 请选择目标就业岗位 --</option>
                <optgroup v-for="group in positionGroups" :key="group.name" :label="group.name">
                  <option v-for="pos in group.positions" :key="pos.key" :value="pos.key">{{ pos.label }}</option>
                </optgroup>
              </select>
              <div class="select-arrow">▼</div>
            </div>
          </div>

          <section class="top-section" v-if="selectedPosition && currentSkills.length > 0">
            <div class="section-block-header">
              <div class="section-block-title">
                <span class="block-icon">📋</span>
                <span>岗位技能清单</span>
                <span class="block-divider"></span>
                <span class="block-subtitle">{{ selectedPositionLabel }} · 共 {{ currentSkills.length }} 项技能要求</span>
              </div>
              <div class="section-block-deco"></div>
            </div>
            <div class="skill-categories">
              <div v-for="category in categorizedSkills" :key="category.name" class="skill-category">
                <h4 class="category-title">{{ category.name }}</h4>
                <div class="skill-tags">
                  <span 
                    v-for="skill in category.skills" 
                    :key="skill.name" 
                    class="skill-tag"
                    :class="'level-' + skill.level"
                  >
                    {{ skill.name }}
                    <span class="level-badge">{{ levelLabels[skill.level] }}</span>
                  </span>
                </div>
              </div>
            </div>
          </section>

          <section class="bottom-section">
            <div class="section-block-header">
              <div class="section-block-title">
                <span class="block-icon">🎓</span>
                <span>学习资源推送</span>
                <span class="block-divider"></span>
                <span class="block-subtitle">系统主动推送 · 每项技能至少匹配1份权威资源</span>
              </div>
              <div class="section-block-deco"></div>
            </div>
            <!-- 资源匹配加载提示横幅（岗位切换时显示，区域锁定防止重复请求） -->
            <div v-if="loadingResources" class="resource-loading-banner">
              <span class="loading-spinner"></span>
              <span>正在匹配对应技能学习资源，请稍等...</span>
            </div>
            <div class="resource-cards resource-cards-grid">
              <div
                v-for="card in pagedResourceCards"
                :key="card.id"
                class="resource-card"
                :class="{ 'featured': card.featured }"
              >
                <div class="card-header">
                  <div class="card-header-left">
                    <span class="push-badge">
                      <span class="push-icon">⚡</span>
                      <span>系统推送</span>
                    </span>
                    <span class="card-type">{{ card.typeLabel }}</span>
                  </div>
                  <div class="card-rating" v-if="card.rating">
                    <span class="rating-star">★</span>
                    <span>{{ card.rating.toFixed(1) }}</span>
                  </div>
                </div>
                <h3 class="card-title">{{ card.title }}</h3>
                <p class="card-desc" v-if="card.desc">{{ card.desc }}</p>
                <div class="card-meta-row">
                  <div class="meta-item" v-if="card.matchedSkills && card.matchedSkills.length > 0">
                    <span class="meta-icon">🎯</span>
                    <span class="meta-label">匹配技能：</span>
                    <span class="meta-skills">{{ card.matchedSkills.slice(0, 3).map(s => s.name).join('、') }}{{ card.matchedSkills.length > 3 ? ` 等${card.matchedSkills.length}项` : '' }}</span>
                  </div>
                  <div class="meta-item-right">
                    <span class="relevance-badge" v-if="card.relevanceScore" :class="'level-' + getRelevanceLevel(card.relevanceScore)">
                      <span class="relevance-icon">📊</span>
                      <span>匹配度 {{ Math.round(card.relevanceScore) }}%</span>
                    </span>
                  </div>
                </div>
                <div class="card-footer">
                  <span class="time-label">⏱ {{ card.durationText }}</span>
                  <span class="level-label" :class="'level-' + card.difficulty">{{ card.difficulty }}</span>
                  <span class="source-label" v-if="card.provider">{{ card.provider }}</span>
                  <span class="quality-badge" v-if="card.isHighlyRelevant">
                    <span class="quality-icon">✓</span>
                    <span>强相关</span>
                  </span>
                </div>
                <button
                  class="card-action-btn"
                  v-if="card.url || card.externalUrl"
                  @click.stop="openResource(card)"
                >
                  🚀 前往学习
                </button>
                <div class="card-collapse-toggle" @click="toggleCardExpand(card.id)">
                  <span class="toggle-icon" :class="{ expanded: expandedCards[card.id] }">▼</span>
                  <span class="toggle-text">{{ expandedCards[card.id] ? '收起详情' : '展开实践方案与工具' }}</span>
                </div>
                <div class="card-collapse-panel" v-if="expandedCards[card.id]">
                  <div class="collapse-section" v-if="card.practicePlan && card.practicePlan.length > 0">
                    <h5 class="collapse-title">
                      <span class="collapse-icon">💪</span> 实践练习方案
                    </h5>
                    <ol class="practice-list">
                      <li v-for="(step, sIdx) in card.practicePlan" :key="sIdx">{{ step }}</li>
                    </ol>
                  </div>
                  <div class="collapse-section" v-else>
                    <h5 class="collapse-title">
                      <span class="collapse-icon">💡</span> 学习建议
                    </h5>
                    <p class="collapse-placeholder">建议结合该资源类型制定学习计划，完成核心知识点学习并动手实践。</p>
                  </div>
                  <div class="collapse-section" v-if="card.recommendedTools && card.recommendedTools.length > 0">
                    <h5 class="collapse-title">
                      <span class="collapse-icon">🛠</span> 配套推荐工具
                    </h5>
                    <ul class="tools-list">
                      <li v-for="(tool, tIdx) in card.recommendedTools" :key="tIdx">{{ tool }}</li>
                    </ul>
                  </div>
                  <div class="collapse-section" v-else>
                    <h5 class="collapse-title">
                      <span class="collapse-icon">🛠</span> 配套推荐工具
                    </h5>
                    <p class="collapse-placeholder">推荐使用 VS Code + Git + Chrome DevTools 进行开发实践。</p>
                  </div>
                </div>
              </div>
            </div>
            <!-- 分页控件 -->
            <div v-if="totalResourcePages > 1" class="resource-pagination">
              <div class="pagination-info">
                <span class="pagination-current">{{ resourcePage }}</span>
                <span class="pagination-sep">/</span>
                <span class="pagination-total-pages">{{ totalResourcePages }}</span>
                <span class="pagination-total-count">共 {{ resourceCards.length }} 条资源</span>
              </div>
              <div class="pagination-controls">
                <button
                  class="pagination-btn pagination-prev"
                  :disabled="resourcePage <= 1"
                  @click="changeResourcePage(resourcePage - 1)"
                  title="上一页"
                >
                  <svg class="pagination-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                    <polyline points="14 18 8 12 14 6"></polyline>
                  </svg>
                </button>
                <div class="pagination-pages">
                  <template v-for="p in totalResourcePages">
                    <button
                      v-if="p === 1 || p === totalResourcePages || Math.abs(p - resourcePage) <= 1"
                      :key="'page-' + p"
                      class="pagination-page-btn"
                      :class="{ active: p === resourcePage }"
                      @click="changeResourcePage(p)"
                    >{{ p }}</button>
                    <span v-else-if="Math.abs(p - resourcePage) === 2" :key="'ellipsis-' + p" class="pagination-ellipsis">...</span>
                  </template>
                </div>
                <button
                  class="pagination-btn pagination-next"
                  :disabled="resourcePage >= totalResourcePages"
                  @click="changeResourcePage(resourcePage + 1)"
                  title="下一页"
                >
                  <svg class="pagination-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
                    <polyline points="10 18 16 12 10 6"></polyline>
                  </svg>
                </button>
              </div>
            </div>
            <!-- 游客模式：资源被截断底部提示（资源不足2条时不展示，避免误导） -->
            <div v-if="hasTruncatedResources" class="resource-truncate-hint" @click="showLoginModal()">
              <span class="truncate-icon">🔒</span>
              <span>还有更多权威学习资源，登录账号解锁全部内容</span>
              <span class="truncate-arrow">→</span>
            </div>
          </section>

          <div class="rules-section">
            <div class="rules-column">
              <h4 class="rules-title">
                <span class="title-icon">🎯</span>
                <span>智能推送规则</span>
              </h4>
              <div class="rules-badge-row">
                <span class="rule-badge badge-primary">目标：{{ selectedPositionLabel }}</span>
                <span class="rule-badge badge-success">精准匹配</span>
                <span class="rule-badge badge-warning">实时更新</span>
              </div>
              <ul class="rules-list">
                <li>
                  <span class="rule-icon">📌</span>
                  <span class="rule-text">
                    <strong>岗位驱动推送</strong>：基于JD技能要求动态匹配
                  </span>
                </li>
                <li>
                  <span class="rule-icon">🔍</span>
                  <span class="rule-text">
                    <strong>三级匹配引擎</strong>：精准库匹配 → AI智能生成 → 知识库兜底
                  </span>
                </li>
                <li>
                  <span class="rule-icon">📊</span>
                  <span class="rule-text">
                    <strong>多类型资源</strong>：官方文档 / 视频课程 / 实战教程 / 图书教材
                  </span>
                </li>
                <li>
                  <span class="rule-icon">🎯</span>
                  <span class="rule-text">
                    <strong>全技能覆盖</strong>：必备技能100%覆盖，优先/加分技能智能补充
                  </span>
                </li>
                <li>
                  <span class="rule-icon">🎓</span>
                  <span class="rule-text">
                    <strong>难度适配</strong>：根据学习进度动态调整资源难度等级
                  </span>
                </li>
              </ul>
            </div>
            <div class="rules-column">
              <h4 class="rules-title">
                <span class="title-icon">⚙️</span>
                <span>推送机制详解</span>
              </h4>
              <div class="rules-flow">
                <div class="flow-step">
                  <span class="flow-num">1</span>
                  <span class="flow-label">技能解析</span>
                  <span class="flow-value">权重10分/项</span>
                </div>
                <div class="flow-arrow">→</div>
                <div class="flow-step">
                  <span class="flow-num">2</span>
                  <span class="flow-label">资源筛选</span>
                  <span class="flow-value">相关性≥60%</span>
                </div>
                <div class="flow-arrow">→</div>
                <div class="flow-step">
                  <span class="flow-num">3</span>
                  <span class="flow-label">质量校验</span>
                  <span class="flow-value">评分≥4.5</span>
                </div>
              </div>
              <ul class="rules-list">
                <li>
                  <span class="rule-icon">⚖️</span>
                  <span class="rule-text">
                    <strong>权重分级</strong>：必备技能10分/项，优先技能5分/项，加分技能2分/项
                  </span>
                </li>
                <li>
                  <span class="rule-icon">🔄</span>
                  <span class="rule-text">
                    <strong>多模态保障</strong>：每项技能至少1份文档 + 1个视频课程
                  </span>
                </li>
                <li>
                  <span class="rule-icon">✅</span>
                  <span class="rule-text">
                    <strong>实时链接校验</strong>：失效资源自动过滤，确保资源可访问
                  </span>
                </li>
                <li>
                  <span class="rule-icon">🔔</span>
                  <span class="rule-text">
                    <strong>每日巡检更新</strong>：资源库每日自动巡检，保证新鲜有效
                  </span>
                </li>
                <li>
                  <span class="rule-icon">📈</span>
                  <span class="rule-text">
                    <strong>学习轨迹追踪</strong>：基于你的学习行为动态优化推荐策略
                  </span>
                </li>
              </ul>
            </div>
          </div>
        </div>

        <!-- AI学习顾问视图 -->
        <div v-else-if="currentNav === 'ai-assistant'" class="view-section ai-view">
          <div class="content-header">
            <h2>AI学习顾问</h2>
            <p class="content-desc">AI学习助手，为你规划学习路径、解答技术疑问、模拟面试、推荐学习资源</p>
            <div v-if="isLocalFallbackMode" class="ai-offline-banner">
              <span class="offline-icon">{{ cozeCreditExhausted ? '💡' : '📚' }}</span>
              <span v-if="cozeCreditExhausted">AI服务额度不足，当前使用本地知识库回答。核心功能（学习路线/模拟面试/技术问答）仍可使用。</span>
              <span v-else>当前为本地知识库模式，回答基于本地数据。核心功能（学习路线/模拟面试/技术问答）仍可使用。</span>
              <button class="offline-close" @click="isLocalFallbackMode = false; cozeCreditExhausted = false">✕</button>
            </div>
            <div class="ai-header-actions">
              <span v-if="aiMessages.length > 1" class="ai-memory-hint">📝 已记住你的对话历史</span>
              <button v-if="aiMessages.length > 1" class="ai-clear-btn" @click="clearAIHistory">🗑️ 清除历史</button>
            </div>
          </div>
          <div class="ai-chat-container">
            <div class="ai-chat-messages" ref="aiChatMessagesRef">
              <div 
                v-for="(msg, idx) in aiMessages" 
                :key="msg.id || idx" 
                class="ai-chat-message" 
                :class="[msg.role, msg.isStreaming ? 'streaming' : '']"
              >
                <div class="message-avatar">
                  <span v-if="msg.role === 'user'">👤</span>
                  <span v-else>🤖</span>
                </div>
                <div class="message-content">
                  <div v-if="msg.role === 'assistant' && idx === 0 && !msg.content" class="ai-welcome">
                    <p>你好！我是AI学习顾问。我可以帮你：</p>
                    <ul>
                      <li>🎯 规划学习路径，制定学习计划</li>
                      <li>💡 解答技术疑问，讲解知识点</li>
                      <li>📚 推荐学习资源和实战项目</li>
                      <li>🚀 模拟面试，提供求职建议</li>
                    </ul>
                    <p class="ai-suggestion-title">试试这样问我：</p>
                    <ul class="ai-suggestions">
                      <li v-for="(sug, si) in aiSuggestions" :key="si" @click="useSuggestion(sug)">{{ sug }}</li>
                    </ul>
                  </div>
                  <div v-else class="message-text">
                    <div v-if="msg.files && msg.files.length > 0" class="message-files">
                      <div v-for="(f, fi) in msg.files" :key="fi" class="msg-file-item">
                        <img v-if="f.isImage && f.previewUrl" :src="f.previewUrl" class="msg-file-img" @click="previewImage(f.previewUrl)" />
                        <img v-else-if="f.isImage" :src="getFileIcon(f)" class="msg-file-img" />
                        <div v-else class="msg-file-doc">
                          <span>{{ f.icon || '📎' }}</span>
                          <span class="msg-file-name">{{ f.name }}</span>
                        </div>
                      </div>
                    </div>
                    <span>{{ stripMarkdown(msg.content) }}</span>
                    <span v-if="msg.isStreaming" class="cursor">|</span>
                  </div>
                </div>
              </div>
              <!-- 加载气泡：用户发送后显示，AI开始返回时消失 -->
              <div v-if="aiLoading && !aiStreamStarted" class="ai-chat-message assistant loading-bubble">
                <div class="message-avatar">🤖</div>
                <div class="message-content loading-content">
                  <div class="loading-dots">
                    <span></span><span></span><span></span>
                  </div>
                  <span class="loading-text">正在思考，请稍等片刻...</span>
                </div>
              </div>
            </div>
            <!-- 游客模式：剩余对话次数提示 -->
            <div v-if="isGuestMode && !aiChatLocked" class="ai-guest-hint">
              <span class="guest-hint-icon">🎫</span>
              <span>游客模式：剩余 <strong>{{ guestAIChatRemaining }}</strong>/{{ GUEST_LIMITS.MAX_AI_CHAT_ROUNDS }} 轮对话</span>
            </div>
            <!-- 游客模式：对话次数已用完提示 -->
            <div v-if="isGuestMode && aiChatLocked" class="ai-guest-hint exhausted">
              <span class="guest-hint-icon">🔒</span>
              <span>对话次数已用完，登录后可无限制使用</span>
            </div>
            <!-- 已选文件预览区 -->
            <div v-if="aiSelectedFiles.length > 0" class="ai-file-preview">
              <div v-for="(file, idx) in aiSelectedFiles" :key="idx" class="file-preview-item">
                <div v-if="file.isImage" class="file-preview-image">
                  <img :src="file.previewUrl" :alt="file.name" />
                </div>
                <div v-else class="file-preview-doc">
                  <span class="file-icon">{{ file.icon }}</span>
                  <span class="file-name">{{ file.name }}</span>
                  <span class="file-size">{{ file.sizeText }}</span>
                </div>
                <button class="file-remove" @click="removeFile(idx)">✕</button>
              </div>
            </div>
            <div class="ai-chat-input" :class="{ locked: aiLoading || aiChatLocked }">
              <button 
                class="ai-upload-btn" 
                @click="triggerFileUpload"
                :disabled="aiLoading || aiChatLocked"
                title="上传图片或文件"
              >
                📎
              </button>
              <input 
                ref="aiFileInputRef" 
                type="file" 
                multiple 
                accept="image/*,.pdf,.doc,.docx,.txt,.js,.vue,.json,.zip,.md,.html,.css,.java,.py"
                style="display:none"
                @change="handleFileSelect"
              />
              <input 
                v-model="aiMessageInput" 
                type="text" 
                :placeholder="aiChatLocked ? '对话次数已用完，请登录解锁' : '输入你的学习问题...'" 
                @keydown.enter="sendAIMessage"
                :disabled="aiLoading || aiChatLocked"
              >
              <button 
                class="ai-send-btn" 
                @click="sendAIMessage"
                :disabled="aiLoading || (!aiMessageInput.trim() && aiSelectedFiles.length === 0) || aiChatLocked"
              >
                {{ aiLoading ? '思考中...' : (aiChatLocked ? '已锁定' : '发送') }}
              </button>
            </div>
          </div>
        </div>
      </main>
    </div>
    <!-- 登录弹窗（游客模式功能受限时唤起，页面内弹窗+蒙层，禁止底层滚动） -->
    <LoginModal />
  </div>
</template>

<script setup>
import { ref, computed, watch, onMounted, onUnmounted } from 'vue'
import { useRouter } from 'vue-router'
import { findMatchingResources, typeLabels } from '@/data/resources.js'
import { generateLearningRoute } from '@/data/positionSkills.js'
import { useGuestMode } from '@/composables/useGuestMode'
import { authFetch, getAuthHeaders } from '@/utils/auth'
import { processLocalAIResponse } from '@/utils/localAIFallback.js'
import LoginModal from '@/components/LoginModal.vue'

const router = useRouter()
const bgCanvas = ref(null)
const currentNav = ref('resource-lib')
const aiInput = ref('')
const selectedPosition = ref('')

// ========== 游客模式状态（统一权限管理） ==========
const {
  isGuestMode,
  guestAIChatCount,
  guestAIChatRemaining,
  GUEST_LIMITS,
  checkPermission,
  isGuestAIChatExhausted,
  incrementGuestAIChat,
  resetGuestAIChatCount,
  showLoginModal,
  refreshAuthState
} = useGuestMode()

// 资源截断标记：记录每个技能是否还有更多资源被隐藏（用于展示"解锁更多资源"提示）
const resourceTruncatedMap = ref({})

// 游客AI对话是否已锁定（达到3轮上限）
const aiChatLocked = computed(() => isGuestAIChatExhausted())

// 是否有资源被截断（游客模式下，某技能资源数超过配额时显示"解锁更多资源"提示）
// 边界优化：资源不足2条时不展示提示，避免误导
const hasTruncatedResources = computed(() => {
  if (!isGuestMode.value) return false
  for (const skillName of Object.keys(resourceMap.value)) {
    const resources = resourceMap.value[skillName]?.resources || []
    if (resources.length > GUEST_LIMITS.MAX_RESOURCES_PER_SKILL) {
      return true
    }
  }
  return false
})

// ========== 学习资源后端驱动状态 ==========
// 三级匹配：后端 /match-position 返回按技能分组的资源；失败时降级到本地 findMatchingResources
const resourceMap = ref({})         // 后端返回的按技能分组数据 { [skillName]: { resources, practiceTip, tools } }
const loadingResources = ref(false)  // 加载状态（区域锁定，防止重复请求）
const resourceError = ref(false)     // 错误标志（触发本地兜底，前端不弹报错）

// 学习数据统计
const learnedCount = ref(3)
const totalHours = ref(12)
const masteryRate = ref(68)
const streakDays = ref(5)

// 技能进度列表
const topSkills = computed(() => {
  if (!selectedPosition.value || currentSkills.value.length === 0) {
    return [
      { name: 'HTML/CSS', progress: 85 },
      { name: 'JavaScript', progress: 72 },
      { name: 'Vue/React', progress: 60 },
      { name: '工程化工具', progress: 45 }
    ]
  }
  return currentSkills.value.slice(0, 6).map((skill, idx) => ({
    name: skill.name,
    progress: Math.max(30, 90 - idx * 12)
  }))
})

// 学习计划列表
const studyPlans = computed(() => {
  if (!selectedPosition.value) return []
  const positionLabel = selectedPositionLabel.value || '目标岗位'
  return [
    {
      id: 1,
      title: `${positionLabel}基础技能学习`,
      desc: '掌握岗位所需的核心基础知识',
      progress: 45,
      status: 'ongoing',
      statusText: '进行中',
      deadline: '2026-08-30',
      goal: '完成10个核心技能学习'
    },
    {
      id: 2,
      title: '实战项目训练',
      desc: '通过实战项目巩固所学知识',
      progress: 20,
      status: 'pending',
      statusText: '待开始',
      deadline: '2026-09-15',
      goal: '完成3个完整项目'
    }
  ]
})

// AI聊天相关变量
const AI_HISTORY_KEY = 'ai-chat-history'
const AI_CONVERSATION_KEY = 'ai-conversation-id'
const AI_USER_KEY = 'ai-user-id'
const AI_HISTORY_MAX = 100

const DEFAULT_WELCOME_MESSAGE = { role: 'assistant', content: '', isStreaming: false }

const loadAIHistory = () => {
  try {
    const saved = localStorage.getItem(AI_HISTORY_KEY)
    if (saved) {
      const parsed = JSON.parse(saved)
      if (Array.isArray(parsed) && parsed.length > 0) {
        return parsed.filter(m => m && m.role && !m.isStreaming)
      }
    }
  } catch (e) {
    console.warn('[AI] 历史记录加载失败:', e)
  }
  return null
}

const saveAIHistory = () => {
  try {
    const toSave = aiMessages.value
      .filter(m => !m.isStreaming)
      .map(m => {
        const saved = { role: m.role, content: m.content, id: m.id }
        if (m.files && m.files.length > 0) {
          saved.files = m.files.map(f => ({
            name: f.name,
            isImage: f.isImage,
            icon: f.icon,
            sizeText: f.sizeText
          }))
        }
        return saved
      })
      .slice(-AI_HISTORY_MAX)
    localStorage.setItem(AI_HISTORY_KEY, JSON.stringify(toSave))
  } catch (e) {
    console.warn('[AI] 历史记录保存失败:', e)
  }
}

const loadAIConversationId = () => {
  try {
    const saved = localStorage.getItem(AI_CONVERSATION_KEY)
    if (saved) return saved
  } catch (e) {}
  return ''
}

const saveAIConversationId = (id) => {
  if (id) {
    localStorage.setItem(AI_CONVERSATION_KEY, id)
    aiConversationId.value = id
  }
}

const loadAIUserId = () => {
  try {
    const saved = localStorage.getItem(AI_USER_KEY)
    if (saved) return saved
  } catch (e) {}
  const newId = 'user-' + Date.now()
  localStorage.setItem(AI_USER_KEY, newId)
  return newId
}

const aiMessages = ref([])
const aiMessageInput = ref('')
const aiLoading = ref(false)
const aiStreamStarted = ref(false)
const aiConversationId = ref('')
const aiUserId = ref('')
const aiChatMessagesRef = ref(null)
const isLocalFallbackMode = ref(false)
const cozeCreditExhausted = ref(false)
let msgIdCounter = 0

// 文件上传相关状态
const aiFileInputRef = ref(null)
const aiSelectedFiles = ref([])

const FILE_ICONS = {
  pdf: '📄', doc: '📝', docx: '📝', txt: '📃', js: '⚡', vue: '💚',
  json: '📋', zip: '📦', md: '📑', html: '🌐', css: '🎨',
  java: '☕', py: '🐍', ppt: '📊', pptx: '📊', xls: '📗', xlsx: '📗'
}

const triggerFileUpload = () => {
  aiFileInputRef.value?.click()
}

const handleFileSelect = (e) => {
  const files = Array.from(e.target.files || [])
  for (const file of files) {
    if (aiSelectedFiles.value.length >= 5) {
      alert('最多只能上传5个文件')
      break
    }
    const ext = file.name.split('.').pop().toLowerCase()
    const isImage = file.type.startsWith('image/')
    const fileInfo = {
      raw: file,
      name: file.name,
      size: file.size,
      sizeText: formatFileSize(file.size),
      isImage,
      icon: isImage ? '🖼️' : (FILE_ICONS[ext] || '📎'),
      previewUrl: isImage ? URL.createObjectURL(file) : null
    }
    aiSelectedFiles.value.push(fileInfo)
  }
  e.target.value = ''
}

const removeFile = (idx) => {
  const file = aiSelectedFiles.value[idx]
  if (file?.previewUrl) URL.revokeObjectURL(file.previewUrl)
  aiSelectedFiles.value.splice(idx, 1)
}

const clearFiles = () => {
  aiSelectedFiles.value.forEach(f => { if (f.previewUrl) URL.revokeObjectURL(f.previewUrl) })
  aiSelectedFiles.value = []
}

const formatFileSize = (bytes) => {
  if (bytes < 1024) return bytes + ' B'
  if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB'
  return (bytes / 1024 / 1024).toFixed(1) + ' MB'
}

const previewImage = (url) => {
  window.open(url, '_blank')
}

const getFileIcon = (f) => {
  return f.icon || '🖼️'
}

const clearAIHistory = () => {
  if (!confirm('确定要清除所有对话历史吗？这将删除与AI顾问的所有对话记录。')) return
  localStorage.removeItem(AI_HISTORY_KEY)
  localStorage.removeItem(AI_CONVERSATION_KEY)
  aiMessages.value = [{ ...DEFAULT_WELCOME_MESSAGE }]
  aiConversationId.value = ''
  msgIdCounter = 0
  console.log('[AI] 历史记录已清除')
}

const initAIHistory = () => {
  aiUserId.value = loadAIUserId()
  aiConversationId.value = loadAIConversationId()
  const history = loadAIHistory()
  if (history && history.length > 0) {
    aiMessages.value = history
    msgIdCounter = history.length
    console.log('[AI] 历史记录已加载，共', history.length, '条消息')
  } else {
    aiMessages.value = [{ ...DEFAULT_WELCOME_MESSAGE }]
  }
}

const aiSuggestions = [
  '如何系统学习前端开发？',
  'Vue和React哪个更适合新手？',
  '我想转行IT，需要学哪些技能？',
  '如何准备前端面试？',
  '推荐一些JavaScript进阶学习资源'
]

const stripMarkdown = (text) => {
  if (!text) return ''
  return text
    .replace(/```[\s\S]*?```/g, '')
    .replace(/`[^`]*`/g, '')
    .replace(/^#{1,6}\s+/gm, '')
    .replace(/\*\*(.+?)\*\*/g, '$1')
    .replace(/\*(.+?)\*/g, '$1')
    .replace(/__(.+?)__/g, '$1')
    .replace(/_(.+?)_/g, '$1')
    .replace(/~~(.+?)~~/g, '$1')
    .replace(/^>\s+/gm, '')
    .replace(/^[-*+]\s+/gm, '• ')
    .replace(/^\d+\.\s+/gm, '')
    .replace(/\[([^\]]+)\]\([^)]+\)/g, '$1')
    .replace(/<[^>]+>/g, '')
    .replace(/<\/?details>/g, '')
    .replace(/<summary>/g, '【')
    .replace(/<\/summary>/g, '】')
    .replace(/<[^>]+>/g, '')
    .replace(/\n{3,}/g, '\n\n')
}

const useSuggestion = (text) => {
  aiMessageInput.value = text
  sendAIMessage()
}

const scrollChatToBottom = () => {
  if (aiChatMessagesRef.value) {
    aiChatMessagesRef.value.scrollTop = aiChatMessagesRef.value.scrollHeight
  }
}

const sendAIMessage = async () => {
  const message = aiMessageInput.value.trim()
  const hasFiles = aiSelectedFiles.value.length > 0
  if ((!message && !hasFiles) || aiLoading.value) return

  // 游客对话次数校验：达到3轮上限后锁定输入框，弹出登录提示
  if (isGuestMode.value && isGuestAIChatExhausted()) {
    showLoginModal('您当前为游客模式，对话次数已用完。注册登录后，可无限制使用AI学习顾问！')
    return
  }

  aiLoading.value = true
  aiStreamStarted.value = false

  // 收集文件信息用于消息显示
  const fileDisplayInfos = aiSelectedFiles.value.map(f => ({
    name: f.name,
    isImage: f.isImage,
    icon: f.icon,
    previewUrl: f.previewUrl,
    sizeText: f.sizeText
  }))

  aiMessageInput.value = ''

  // 游客发送消息后增加计数（一轮 = 用户发送一条消息算作一轮）
  if (isGuestMode.value) {
    incrementGuestAIChat()
  }

  msgIdCounter++
  aiMessages.value.push({
    id: 'user-' + msgIdCounter,
    role: 'user',
    content: message || '📎 发送了文件',
    isStreaming: false,
    files: fileDisplayInfos
  })

  const pendingAssistantIndex = aiMessages.value.length

  scrollChatToBottom()

  const historyForContext = aiMessages.value
    .filter(m => !m.isStreaming && m.content)
    .slice(-10)
    .map(m => ({ role: m.role, content: m.content }))

  // 根据是否有文件选择不同请求方式
  if (hasFiles) {
    await sendWithFiles(message, fileDisplayInfos, historyForContext, pendingAssistantIndex)
  } else {
    await sendTextOnly(message, historyForContext, pendingAssistantIndex)
  }
}

const sendTextOnly = async (message, historyForContext, pendingAssistantIndex) => {
  try {
    const response = await authFetch('/api/ai/chat', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        message: message,
        conversation_id: aiConversationId.value,
        user_id: aiUserId.value,
        history: historyForContext
      })
    })

    if (response.status === 403) {
      const errData = await response.json().catch(() => ({}))
      aiMessages.value.pop()
      if (errData.code === 'GUEST_FORBIDDEN' || errData.code === 'GUEST_AI_LIMIT_EXCEEDED') {
        showLoginModal('您当前为游客模式，对话次数已用完。注册登录后，可无限制使用AI学习顾问！')
      } else {
        showLoginModal(errData.message || '游客模式功能受限，请登录账号解锁完整功能')
      }
      return
    }

    if (!response.ok) {
      throw new Error('请求失败')
    }

    const reader = response.body.getReader()
    const decoder = new TextDecoder()
    let buffer = ''

    while (true) {
      const { done, value } = await reader.read()
      if (done) break

      buffer += decoder.decode(value, { stream: true })
      const lines = buffer.split('\n')
      buffer = lines.pop()

      for (const line of lines) {
        if (line.startsWith('data:')) {
          const dataStr = line.slice(5).trim()
          if (dataStr === '[DONE]') continue

          try {
            const data = JSON.parse(dataStr)
            handleAIResponse(data, pendingAssistantIndex)
          } catch (e) {
          }
        }
      }
    }

    if (aiMessages.value[pendingAssistantIndex]) {
      aiMessages.value[pendingAssistantIndex].isStreaming = false
    }
  } catch (error) {
    console.warn('AI请求失败，启用本地兜底:', error.message)
    await localFallbackResponse(message, historyForContext, pendingAssistantIndex)
  }

  aiLoading.value = false
  aiStreamStarted.value = false
  saveAIHistory()
}

const sendWithFiles = async (message, fileInfos, historyForContext, pendingAssistantIndex) => {
  try {
    const formData = new FormData()
    formData.append('message', message || '请分析我上传的文件')
    formData.append('module', 'general')
    formData.append('conversation_id', aiConversationId.value)
    formData.append('user_id', aiUserId.value)
    formData.append('history', JSON.stringify(historyForContext))
    formData.append('fileCount', String(aiSelectedFiles.value.length))
    formData.append('fileNames', JSON.stringify(aiSelectedFiles.value.map(f => f.name)))

    aiSelectedFiles.value.forEach(f => {
      formData.append('files', f.raw)
    })

    const response = await authFetch('/api/ai-assistant/chat', {
      method: 'POST',
      body: formData
    })

    if (response.status === 403) {
      const errData = await response.json().catch(() => ({}))
      aiMessages.value.pop()
      if (errData.code === 'GUEST_FORBIDDEN' || errData.code === 'GUEST_AI_LIMIT_EXCEEDED') {
        showLoginModal('您当前为游客模式，对话次数已用完。注册登录后，可无限制使用AI学习顾问！')
      } else {
        showLoginModal(errData.message || '游客模式功能受限，请登录账号解锁完整功能')
      }
      clearFiles()
      return
    }

    if (!response.ok) {
      throw new Error('文件上传请求失败')
    }

    const data = await response.json()
    if (data.success && data.data && data.data.reply) {
      msgIdCounter++
      aiMessages.value.splice(pendingAssistantIndex, 0, {
        id: 'assistant-' + msgIdCounter,
        role: 'assistant',
        content: data.data.reply,
        isStreaming: false
      })
    } else {
      throw new Error(data.error || 'AI回复失败')
    }
  } catch (error) {
    console.warn('文件上传请求失败，启用本地兜底:', error.message)
    const fileContext = fileInfos.map(f => `用户上传了文件：${f.name}（${f.sizeText}）`).join('\n')
    const enhancedMessage = (message ? message + '\n\n' : '') + fileContext
    await localFallbackResponse(enhancedMessage, historyForContext, pendingAssistantIndex)
  }

  clearFiles()
  aiLoading.value = false
  aiStreamStarted.value = false
  saveAIHistory()
}

const localFallbackResponse = async (message, historyForContext, pendingAssistantIndex) => {
  aiStreamStarted.value = true

  const localResponse = processLocalAIResponse(message, historyForContext)

  if (!aiMessages.value[pendingAssistantIndex] || aiMessages.value[pendingAssistantIndex].role !== 'assistant') {
    msgIdCounter++
    aiMessages.value.splice(pendingAssistantIndex, 0, {
      id: 'assistant-' + msgIdCounter,
      role: 'assistant',
      content: '',
      isStreaming: true
    })
  }

  const sentences = localResponse.split(/(?<=[。！？\n])/)
  const chunks = sentences.filter(s => s.trim())
  let idx = 0

  aiLoading.value = false
  aiStreamStarted.value = true

  return new Promise((resolve) => {
    const typewriterTimer = setInterval(() => {
      if (idx >= chunks.length) {
        clearInterval(typewriterTimer)
        if (aiMessages.value[pendingAssistantIndex]) {
          aiMessages.value[pendingAssistantIndex].isStreaming = false
        }
        aiStreamStarted.value = false
        saveAIHistory()
        resolve()
        return
      }

      const chunk = chunks[idx]
      if (aiMessages.value[pendingAssistantIndex]) {
        aiMessages.value[pendingAssistantIndex].content += chunk
      }
      idx++
      scrollChatToBottom()
    }, 30)
  })
}

const handleAIResponse = (data, msgIndex) => {
  switch (data.type) {
    case 'delta':
      if (data.content) {
        if (!aiMessages.value[msgIndex]) {
          msgIdCounter++
          aiMessages.value.splice(msgIndex, 0, {
            id: 'assistant-' + msgIdCounter,
            role: 'assistant',
            content: data.content,
            isStreaming: true
          })
        } else {
          aiMessages.value[msgIndex].content += data.content
        }
        aiStreamStarted.value = true
        scrollChatToBottom()
      }
      break

    case 'completed':
      if (data.mode === 'local_fallback') {
        isLocalFallbackMode.value = true
        if (data.cozeNote === 'coze_credit_exhausted') {
          cozeCreditExhausted.value = true
        }
      } else if (data.mode && data.mode !== 'local_fallback') {
        isLocalFallbackMode.value = false
        cozeCreditExhausted.value = false
      }
      if (data.content) {
        if (!aiMessages.value[msgIndex]) {
          msgIdCounter++
          aiMessages.value.splice(msgIndex, 0, {
            id: 'assistant-' + msgIdCounter,
            role: 'assistant',
            content: data.content,
            isStreaming: false
          })
        } else if (!aiMessages.value[msgIndex].content) {
          aiMessages.value[msgIndex].content = data.content
        }
        if (aiMessages.value[msgIndex]) {
          aiMessages.value[msgIndex].isStreaming = false
        }
      }
      break

    case 'conversation_id':
      if (data.conversation_id) {
        saveAIConversationId(data.conversation_id)
      }
      break

    case 'guest_limit':
      // 后端拦截：游客对话次数已用完，移除用户消息并弹出登录提示
      if (aiMessages.value.length > 0 && aiMessages.value[aiMessages.value.length - 1].role === 'user') {
        aiMessages.value.pop()
      }
      showLoginModal(data.message || '您当前为游客模式，对话次数已用完。注册登录后，可无限制使用AI学习顾问！')
      break

    case 'error':
      if (aiMessages.value[msgIndex]) {
        aiMessages.value[msgIndex].content += '\n\n⚠️ ' + (data.message || '未知错误')
        aiMessages.value[msgIndex].isStreaming = false
      } else {
        msgIdCounter++
        aiMessages.value.splice(msgIndex, 0, {
          id: 'assistant-' + msgIdCounter,
          role: 'assistant',
          content: '⚠️ ' + (data.message || '未知错误'),
          isStreaming: false
        })
      }
      break

    case 'done':
      if (aiMessages.value[msgIndex]) {
        aiMessages.value[msgIndex].isStreaming = false
      }
      break
  }
}

// 折叠面板状态：key为卡片id/索引，value为是否展开
const expandedCards = ref({})

// 分页状态：学习资源卡片分页
const resourcePage = ref(1)
const resourcePageSize = ref(6)
const totalResourcePages = computed(() => {
  return Math.max(1, Math.ceil(resourceCards.value.length / resourcePageSize.value))
})
const pagedResourceCards = computed(() => {
  const start = (resourcePage.value - 1) * resourcePageSize.value
  return resourceCards.value.slice(start, start + resourcePageSize.value)
})
const changeResourcePage = (page) => {
  resourcePage.value = Math.max(1, Math.min(totalResourcePages.value, page))
  // 滚动到资源列表顶部
  const container = document.querySelector('.resource-cards-grid')
  if (container) {
    container.scrollIntoView({ behavior: 'smooth', block: 'start' })
  }
}
// 切换岗位时重置分页
watch(selectedPosition, () => {
  resourcePage.value = 1
  expandedCards.value = {}
})

