    radial-gradient(circle at 20% 80%, rgba(0, 212, 255, 0.06) 0%, transparent 35%),
    radial-gradient(circle at 80% 20%, rgba(255, 61, 166, 0.06) 0%, transparent 35%),
    radial-gradient(circle at 60% 60%, rgba(0, 255, 163, 0.03) 0%, transparent 25%);
  pointer-events: none;
  z-index: 1;
  animation: nebulaShift 12s ease-in-out infinite alternate;
}

@keyframes nebulaShift {
  0% { opacity: 0.5; transform: translate(0, 0); }
  50% { opacity: 0.8; }
  100% { opacity: 0.5; transform: translate(15px, -10px); }
}

@keyframes gridPulse {
  0%, 100% { opacity: 0.3; }
  50% { opacity: 0.6; }
}

.bg-canvas {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  z-index: 0;
  pointer-events: none;
}

.page-header {
  position: relative;
  z-index: 10;
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 16px 32px;
  background: linear-gradient(180deg, rgba(5, 8, 26, 0.85) 0%, rgba(5, 8, 26, 0.6) 100%);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-bottom: 1px solid rgba(0, 212, 255, 0.2);
  box-shadow: 0 2px 30px rgba(0, 212, 255, 0.08);
}

.header-left {
  display: flex;
  align-items: center;
  gap: 18px;
}

.back-btn {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 9px 18px;
  background: linear-gradient(135deg, rgba(0, 212, 255, 0.12), rgba(0, 212, 255, 0.04));
  border: 1px solid rgba(0, 212, 255, 0.35);
  border-radius: 24px;
  color: var(--color-cyan);
  cursor: pointer;
  font-size: 0.82rem;
  font-family: var(--font-display);
  font-weight: 500;
  letter-spacing: 0.5px;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

.back-btn:hover {
  background: linear-gradient(135deg, rgba(0, 212, 255, 0.25), rgba(255, 61, 166, 0.1));
  border-color: rgba(0, 212, 255, 0.6);
  box-shadow: 0 0 20px rgba(0, 212, 255, 0.3);
  transform: translateX(-2px);
}

.page-title {
  font-family: var(--font-display);
  font-size: 1.35rem;
  font-weight: 700;
  letter-spacing: 1.5px;
  color: transparent;
  background: linear-gradient(90deg, #00d4ff 0%, #ff3da6 50%, #00ffa3 100%);
  background-clip: text;
  -webkit-background-clip: text;
  margin: 0;
  text-shadow: 0 0 40px rgba(0, 212, 255, 0.3);
}

.page-subtitle {
  font-size: 0.78rem;
  color: var(--color-text-dim);
  font-family: var(--font-body);
  letter-spacing: 0.3px;
}

.header-nav {
  display: flex;
  gap: 6px;
}

.nav-item {
  padding: 9px 18px;
  color: var(--color-text-dim);
  cursor: pointer;
  border-radius: 10px;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  font-size: 0.85rem;
  font-family: var(--font-display);
  font-weight: 500;
  letter-spacing: 0.5px;
  position: relative;
}

.nav-item:hover {
  color: var(--color-cyan);
  background: rgba(0, 212, 255, 0.08);
}

.nav-item.active {
  color: var(--color-cyan);
  background: linear-gradient(135deg, rgba(0, 212, 255, 0.15), rgba(255, 61, 166, 0.08));
  border: 1px solid rgba(0, 212, 255, 0.3);
  box-shadow: 0 0 15px rgba(0, 212, 255, 0.15);
}

.main-layout {
  position: relative;
  z-index: 5;
  display: grid;
  grid-template-columns: 220px 1fr 280px;
  gap: 20px;
  padding: 25px;
  max-width: 1600px;
  margin: 0 auto;
  transition: grid-template-columns 0.3s ease;
}

.main-layout.ai-mode {
  grid-template-columns: 220px 1fr;
  max-width: none;
  width: 100%;
}

.main-layout.no-ai-sidebar {
  grid-template-columns: 220px 1fr;
}

.sidebar {
  background: linear-gradient(180deg, rgba(10, 16, 40, 0.8) 0%, rgba(8, 12, 32, 0.7) 100%);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(0, 212, 255, 0.2);
  border-radius: 16px;
  padding: 20px 16px;
  height: fit-content;
  box-shadow: 
    0 0 30px rgba(0, 212, 255, 0.05),
    inset 0 1px 0 rgba(0, 212, 255, 0.1);
  position: relative;
}

.sidebar::before {
  content: '';
  position: absolute;
  top: 0;
  left: 10%;
  right: 10%;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(0, 212, 255, 0.5), transparent);
  border-radius: 50%;
}

.sidebar-section {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.section-label {
  font-family: var(--font-display);
  font-size: 0.68rem;
  color: rgba(0, 212, 255, 0.7);
  text-transform: uppercase;
  letter-spacing: 2px;
  padding: 0 10px 12px;
  border-bottom: 1px solid rgba(0, 212, 255, 0.12);
  margin-bottom: 12px;
}

.sidebar .nav-item {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 11px 14px;
  border-radius: 10px;
  cursor: pointer;
  transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  font-size: 0.86rem;
  font-family: var(--font-body);
  font-weight: 500;
  color: var(--color-text-dim);
  position: relative;
  border-left: 2px solid transparent;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.sidebar .nav-item .nav-text {
  flex: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.sidebar .nav-item:hover {
  background: linear-gradient(90deg, rgba(0, 212, 255, 0.1), transparent);
  color: var(--color-text);
  border-left-color: rgba(0, 212, 255, 0.5);
  transform: translateX(2px);
}

.sidebar .nav-item.active {
  background: linear-gradient(90deg, rgba(0, 212, 255, 0.2), rgba(255, 61, 166, 0.05));
  color: var(--color-cyan);
  border-left: 2px solid var(--color-cyan);
  box-shadow: 0 0 20px rgba(0, 212, 255, 0.1), inset 0 0 20px rgba(0, 212, 255, 0.05);
}

.nav-icon {
  display: flex;
  align-items: center;
  color: currentColor;
  font-size: 1rem;
}

.content-area {
  background: linear-gradient(180deg, rgba(10, 16, 40, 0.8) 0%, rgba(8, 12, 32, 0.7) 100%);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border: 1px solid rgba(0, 212, 255, 0.2);
  border-radius: 16px;
  padding: 28px;
  min-height: calc(100vh - 140px);
  min-width: 0;
  box-shadow: 
    0 0 40px rgba(0, 212, 255, 0.06),
    inset 0 1px 0 rgba(0, 212, 255, 0.08);
  position: relative;
}

.content-area::before {
  content: '';
  position: absolute;
  top: 0;
  left: 15%;
  right: 15%;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(0, 212, 255, 0.6), rgba(255, 61, 166, 0.4), transparent);
}

.content-area::after {
  content: '';
  position: absolute;
  top: 16px;
  left: 16px;
  right: 16px;
  bottom: 16px;
  border: 1px solid rgba(0, 212, 255, 0.08);
  border-radius: 12px;
  pointer-events: none;
}

.content-header {
  margin-bottom: 28px;
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  flex-wrap: wrap;
  gap: 10px;
}

.content-header > div:first-child {
  flex: 1;
}

.content-header h2 {
  font-family: var(--font-display);
  font-size: 1.35rem;
  font-weight: 700;
  color: var(--color-text);
  margin: 0 0 8px;
  letter-spacing: 1px;
}

.content-desc {
  font-size: 0.85rem;
  color: var(--color-text-dim);
  margin: 0;
  font-family: var(--font-body);
}

.ai-header-actions {
  display: flex;
  align-items: center;
  gap: 10px;
  flex-shrink: 0;
}

.ai-memory-hint {
  font-family: var(--font-display);
  font-size: 0.72rem;
  color: var(--color-cyan);
  background: rgba(0, 212, 255, 0.1);
  padding: 5px 12px;
  border-radius: 16px;
  border: 1px solid rgba(0, 212, 255, 0.25);
  letter-spacing: 0.5px;
}

.ai-clear-btn {
  font-family: var(--font-display);
  font-size: 0.72rem;
  color: rgba(255, 107, 107, 0.9);
  background: rgba(255, 107, 107, 0.1);
  padding: 5px 12px;
  border-radius: 16px;
  border: 1px solid rgba(255, 107, 107, 0.25);
  cursor: pointer;
  transition: all 0.2s;
}

.ai-clear-btn:hover {
  color: #fff;
  background: rgba(255, 107, 107, 0.2);
  border-color: rgba(255, 107, 107, 0.5);
}

.ai-offline-banner {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 16px;
  margin: 12px 0;
  background: linear-gradient(90deg, rgba(255, 181, 71, 0.12), rgba(255, 181, 71, 0.05));
  border: 1px solid rgba(255, 181, 71, 0.35);
  border-radius: 12px;
  color: var(--color-amber);
  font-size: 0.85rem;
  animation: fadeInDown 0.3s ease-out;
}

.ai-offline-banner .offline-icon {
  font-size: 1.1rem;
  flex-shrink: 0;
}

.ai-offline-banner span:last-of-type {
  flex: 1;
  color: rgba(255, 255, 255, 0.85);
}

.ai-offline-banner .offline-close {
  background: none;
  border: none;
  color: rgba(255, 255, 255, 0.5);
  cursor: pointer;
  font-size: 0.9rem;
  padding: 0 4px;
  transition: color 0.2s;
}

.ai-offline-banner .offline-close:hover {
  color: #fff;
}

@keyframes fadeInDown {
  from { opacity: 0; transform: translateY(-10px); }
  to { opacity: 1; transform: translateY(0); }
}

.job-selector {
  display: flex;
  align-items: center;
  gap: 16px;
  padding: 18px 22px;
  background: linear-gradient(135deg, rgba(0, 212, 255, 0.08), rgba(255, 61, 166, 0.04));
  border: 1px solid rgba(0, 212, 255, 0.25);
  border-radius: 14px;
  margin-bottom: 22px;
  position: relative;
  overflow: hidden;
}

.job-selector::before {
  content: '';
  position: absolute;
  top: 0;
  left: -100%;
  width: 100%;
  height: 100%;
  background: linear-gradient(90deg, transparent, rgba(0, 212, 255, 0.05), transparent);
  animation: shimmer 4s infinite;
}

@keyframes shimmer {
  0% { left: -100%; }
  100% { left: 100%; }
}

.selector-label {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 0.88rem;
  color: var(--color-text);
  font-family: var(--font-display);
  font-weight: 600;
  letter-spacing: 0.5px;
  white-space: nowrap;
}

.label-icon {
  font-size: 1.15rem;
  filter: drop-shadow(0 0 8px rgba(0, 212, 255, 0.6));
}

.selector-wrapper {
  position: relative;
  flex: 1;
  max-width: 420px;
}

.position-select {
  width: 100%;
  padding: 11px 40px 11px 16px;
  background: rgba(5, 8, 26, 0.9);
  border: 1px solid rgba(0, 212, 255, 0.35);
  border-radius: 10px;
  color: var(--color-text);
  font-size: 0.88rem;
  font-family: var(--font-body);
  outline: none;
  cursor: pointer;
  appearance: none;
  -webkit-appearance: none;
  transition: all 0.3s;
}

.position-select:focus {
  border-color: var(--color-cyan);
  box-shadow: 0 0 0 2px rgba(0, 212, 255, 0.2), 0 0 20px rgba(0, 212, 255, 0.1);
}

.position-select option,
.position-select optgroup {
  background: #05081a;
  color: var(--color-text);
}

.select-arrow {
  position: absolute;
  right: 14px;
  top: 50%;
  transform: translateY(-50%);
  color: rgba(0, 212, 255, 0.7);
  font-size: 0.75rem;
  pointer-events: none;
}

.top-section,
.bottom-section {
  margin-bottom: 28px;
}

.section-block-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 18px;
  padding-bottom: 14px;
  border-bottom: 1px solid rgba(0, 212, 255, 0.15);
  position: relative;
}

.section-block-header::after {
  content: '';
  position: absolute;
  bottom: -1px;
  left: 0;
  width: 80px;
  height: 2px;
  background: linear-gradient(90deg, var(--color-cyan), var(--color-magenta));
  border-radius: 2px;
}

.section-block-title {
  display: flex;
  align-items: center;
  gap: 10px;
  font-family: var(--font-display);
  font-size: 1.02rem;
  font-weight: 600;
  color: #fff;
}

.block-icon {
  font-size: 1.2rem;
}

.block-divider {
  width: 1px;
  height: 16px;
  background: rgba(74, 158, 255, 0.3);
  margin: 0 4px;
}

.block-subtitle {
  font-size: 0.8rem;
  font-weight: 400;
  color: rgba(74, 158, 255, 0.7);
}

.section-block-deco {
  height: 2px;
  flex: 1;
  margin-left: 20px;
  background: linear-gradient(90deg, rgba(74, 158, 255, 0.3), transparent);
  max-width: 200px;
}

.top-section {
  padding: 18px;
  background: rgba(10, 15, 25, 0.5);
  border: 1px solid rgba(74, 158, 255, 0.15);
  border-radius: 10px;
}

.bottom-section {
  padding: 18px;
  background: rgba(10, 15, 25, 0.3);
  border: 1px solid rgba(0, 212, 170, 0.1);
  border-radius: 10px;
}

.card-collapse-toggle {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  margin-top: 12px;
  padding: 8px;
  background: rgba(74, 158, 255, 0.08);
  border: 1px dashed rgba(74, 158, 255, 0.3);
  border-radius: 8px;
  cursor: pointer;
  font-size: 0.78rem;
  color: rgba(74, 158, 255, 0.8);
  transition: all 0.25s;
  user-select: none;
}

.card-collapse-toggle:hover {
  background: rgba(74, 158, 255, 0.15);
  color: #fff;
  border-color: rgba(74, 158, 255, 0.5);
}

.toggle-icon {
  display: inline-block;
  font-size: 0.65rem;
  transition: transform 0.3s;
}

.toggle-icon.expanded {
  transform: rotate(180deg);
}

.card-collapse-panel {
  margin-top: 12px;
  padding: 14px;
  background: rgba(10, 15, 25, 0.6);
  border: 1px solid rgba(74, 158, 255, 0.15);
  border-radius: 8px;
  animation: slideDown 0.3s ease;
}

@keyframes slideDown {
  from { opacity: 0; transform: translateY(-8px); }
  to { opacity: 1; transform: translateY(0); }
}

.collapse-section {
  margin-bottom: 14px;
}

.collapse-section:last-child {
  margin-bottom: 0;
}

.collapse-title {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 0.85rem;
  font-weight: 600;
  color: #4a9eff;
  margin: 0 0 10px;
}

.collapse-icon {
  font-size: 0.95rem;
}

.practice-list,
.tools-list {
  margin: 0;
  padding-left: 0;
  list-style: none;
}

.practice-list {
  counter-reset: practiceCounter;
}

.practice-list li {
  counter-increment: practiceCounter;
  position: relative;
  padding: 8px 12px 8px 32px;
  margin-bottom: 6px;
  background: rgba(74, 158, 255, 0.06);
  border-left: 2px solid rgba(74, 158, 255, 0.4);
  border-radius: 6px;
  font-size: 0.78rem;
  color: rgba(255, 255, 255, 0.8);
  line-height: 1.5;
}

.practice-list li::before {
  content: counter(practiceCounter);
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  width: 18px;
  height: 18px;
  display: flex;
  align-items: center;
  justify-content: center;
  background: linear-gradient(135deg, #4a9eff, #00d4aa);
  border-radius: 50%;
  font-size: 0.65rem;
  font-weight: 700;
  color: #fff;
}

.tools-list li {
  padding: 6px 12px;
  margin-bottom: 5px;
  background: rgba(0, 212, 170, 0.08);
  border-left: 2px solid rgba(0, 212, 170, 0.4);
  border-radius: 6px;
  font-size: 0.78rem;
  color: rgba(255, 255, 255, 0.8);
  line-height: 1.5;
}

.tools-list li:last-child {
  margin-bottom: 0;
}

.skill-categories {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 16px;
}

.skill-category {
  background: rgba(30, 45, 70, 0.5);
  border: 1px solid rgba(74, 158, 255, 0.1);
  border-radius: 8px;
  padding: 14px;
}

.category-title {
  font-size: 0.88rem;
  font-weight: 600;
  color: #4a9eff;
  margin: 0 0 10px;
  padding-bottom: 8px;
  border-bottom: 1px solid rgba(74, 158, 255, 0.1);
}

.skill-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.skill-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  padding: 5px 10px;
  background: rgba(74, 158, 255, 0.1);
  border: 1px solid rgba(74, 158, 255, 0.2);
  border-radius: 14px;
  font-size: 0.75rem;
  color: rgba(255, 255, 255, 0.85);
  transition: all 0.2s;
}

.skill-tag:hover {
  background: rgba(74, 158, 255, 0.2);
  transform: translateY(-1px);
}

.skill-tag.level-must {
  background: rgba(255, 99, 99, 0.12);
  border-color: rgba(255, 99, 99, 0.3);
  color: #ff8a8a;
}

.skill-tag.level-prefer {
  background: rgba(74, 158, 255, 0.12);
  border-color: rgba(74, 158, 255, 0.3);
  color: #7ab8ff;
}

.skill-tag.level-bonus {
  background: rgba(0, 212, 170, 0.12);
  border-color: rgba(0, 212, 170, 0.3);
  color: #5eead4;
}

.level-badge {
  padding: 1px 6px;
  border-radius: 8px;
  font-size: 0.65rem;
  font-weight: 600;
  background: rgba(255, 255, 255, 0.15);
}

.skill-tag.level-must .level-badge {
  background: rgba(255, 99, 99, 0.3);
}

.skill-tag.level-prefer .level-badge {
  background: rgba(74, 158, 255, 0.3);
}

.skill-tag.level-bonus .level-badge {
  background: rgba(0, 212, 170, 0.3);
}

.card-badge.must {
  background: rgba(255, 99, 99, 0.15);
  border-color: rgba(255, 99, 99, 0.4);
  color: #ff8a8a;
}

.card-badge.prefer {
  background: rgba(74, 158, 255, 0.15);
  border-color: rgba(74, 158, 255, 0.4);
  color: #7ab8ff;
}

.card-badge.bonus {
  background: rgba(0, 212, 170, 0.15);
  border-color: rgba(0, 212, 170, 0.4);
  color: #5eead4;
}

.card-badge.pending {
  background: rgba(255, 170, 74, 0.15);
  border-color: rgba(255, 170, 74, 0.3);
  color: #ffaa4a;
}

.resource-cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
  margin-bottom: 24px;
}

.resource-cards-grid {
  scroll-margin-top: 80px;
}

/* 分页控件 */
.resource-pagination {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 28px;
  padding: 18px 24px;
  background: linear-gradient(135deg, rgba(10, 16, 40, 0.8), rgba(8, 14, 35, 0.7));
  border: 1px solid rgba(0, 212, 255, 0.2);
  border-radius: 14px;
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
}

.pagination-info {
  display: flex;
  align-items: baseline;
  gap: 6px;
}

.pagination-current {
  font-family: var(--font-display);
  font-size: 28px;
  font-weight: 700;
  background: linear-gradient(135deg, var(--color-cyan), var(--color-magenta));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.pagination-sep {
  font-size: 20px;
  color: rgba(255, 255, 255, 0.3);
  font-weight: 300;
}

.pagination-total-pages {
  font-size: 18px;
  color: var(--color-text-dim);
  font-weight: 500;
}

.pagination-total-count {
  font-size: 12px;
  color: rgba(255, 255, 255, 0.4);
  margin-left: 10px;
  padding-left: 10px;
  border-left: 1px solid rgba(255, 255, 255, 0.1);
}

.pagination-controls {
  display: flex;
  align-items: center;
  gap: 8px;
}

.pagination-btn {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  background: linear-gradient(135deg, rgba(0, 212, 255, 0.1), rgba(255, 61, 166, 0.05));
  border: 1px solid rgba(0, 212, 255, 0.25);
  color: var(--color-text);
  border-radius: 10px;
  cursor: pointer;
  transition: all 0.25s ease;
}

.pagination-btn:hover:not(:disabled) {
  background: linear-gradient(135deg, rgba(0, 212, 255, 0.3), rgba(255, 61, 166, 0.15));
  border-color: var(--color-cyan);
  color: #fff;
  transform: translateY(-2px);
  box-shadow: 0 6px 20px rgba(0, 212, 255, 0.25);
}

